import React, { useState } from "react";
import {
  Button,
  Card,
  CardHeader,
  CardBody,
  FormGroup,
  Form,
  Input,
  Container,
  Row,
  Col,
  Collapse,
  Alert,
} from "reactstrap";
import UserHeader from "components/Headers/UserHeader.js";
import { getDatabase, ref, set } from "firebase/database"; // Firebase imports
import { getAuth } from "firebase/auth"; // For user authentication

const CarbonFootprintInput = () => {
  const [collapse, setCollapse] = useState({
    transportation: false,
    energy: false,
    food: false,
    waste: false,
    sustainable: false,
    offset: false,
    additionalNotes: false,
  });

  const [userData, setUserData] = useState({
    carUsageKm: "",
    vehicleType: "",
    fuelType: "",
    publicTransportTrips: "",
    publicTransportMode: "",
    flightsPerYear: "",
    electricityUsage: "",
    heatingMethod: "",
    homeSize: "",
    energyEfficientAppliances: false,
    dietType: "",
    meatFrequency: "",
    recyclingHabit: false,
    wasteGeneration: "",
    renewableEnergyUse: false,
    ecoFriendlyProducts: false,
    sustainableShopping: false,
    carbonOffsetProgram: "",
    carbonOffsetDetails: "",
    additionalNotes: "",
  });

  const [formStatus, setFormStatus] = useState(null); // To manage confirmation message state

  const handleChange = (e) => {
    const { id, value, type, checked } = e.target;
    setUserData({
      ...userData,
      [id]: type === "checkbox" ? checked : value,
    });
  };

  const toggleCollapse = (section) => {
    setCollapse((prevState) => ({
      ...prevState,
      [section]: !prevState[section],
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // Log the data for debugging
    console.log("Form Data Submitted:", userData);

    // Check for missing required fields
    const missingFields = [];
    for (let field in userData) {
      if (userData[field] === "" || userData[field] === false) {
        missingFields.push(field);
      }
    }

    // If there are missing fields, return early and log them
    if (missingFields.length > 0) {
      console.log("Missing fields: ", missingFields);
      setFormStatus({ type: "error", message: "Please fill in all required fields!" });
      return;
    }

    // Log successful form submission attempt
    console.log("No missing fields, proceeding with submission.");

    // Get the user's ID from Firebase Authentication (assuming user is logged in)
    const user = getAuth().currentUser;
    const userId = user ? user.uid : null;

    if (userId) {
      try {
        // Initialize Firebase database
        const db = getDatabase();
        const userRef = ref(db, `users/${userId}/userfootprint`);
        await set(userRef, userData);

        console.log("Data successfully saved to Firebase");

        // Confirmation message on successful submission
        setFormStatus({
          type: "success",
          message: "Your carbon footprint data has been successfully submitted!",
        });
      } catch (error) {
        console.error("Error saving data to Firebase:", error);
        setFormStatus({
          type: "error",
          message: "There was an error saving your data. Please try again.",
        });
      }
    } else {
      console.log("User is not logged in.");
      setFormStatus({
        type: "error",
        message: "You must be logged in to submit your data.",
      });
    }
  };

  return (
    <>
      <UserHeader />
      <Container className="mt--7" fluid>
        <Row>
          <Col xl="12">
            <Card className="shadow">
              <CardHeader>
                <h3 className="mb-0">Track Your Carbon Footprint</h3>
                <p className="text-muted">
                  Fill out the form to estimate and track your carbon footprint.
                </p>
              </CardHeader>
              <CardBody>
                {/* Form Status (Confirmation/Error) */}
                {formStatus && (
                  <Alert color={formStatus.type === "error" ? "danger" : "success"}>
                    {formStatus.message}
                  </Alert>
                )}

                <Form onSubmit={handleSubmit}>
                  {/* Transportation Section */}
                  <h6 className="heading-small text-muted mb-4">
                    Transportation
                    <Button
                      color="link"
                      onClick={() => toggleCollapse("transportation")}
                      size="sm"
                      className="float-right"
                    >
                      {collapse.transportation ? "Hide" : "Show"} Details
                    </Button>
                  </h6>
                  <Collapse isOpen={collapse.transportation}>
                    <Row>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="carUsageKm">Number of kilometers driven daily</label>
                          <Input
                            id="carUsageKm"
                            type="number"
                            value={userData.carUsageKm}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="vehicleType">Type of vehicle</label>
                          <Input
                            id="vehicleType"
                            type="text"
                            value={userData.vehicleType}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="fuelType">Fuel type</label>
                          <Input
                            id="fuelType"
                            type="text"
                            value={userData.fuelType}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                    </Row>
                    <Row>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="publicTransportTrips">Number of trips taken weekly</label>
                          <Input
                            id="publicTransportTrips"
                            type="number"
                            value={userData.publicTransportTrips}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="publicTransportMode">Mode of transport</label>
                          <Input
                            id="publicTransportMode"
                            type="text"
                            value={userData.publicTransportMode}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                      <Col md="6">
                        <FormGroup>
                          <label htmlFor="flightsPerYear">Number of flights per year</label>
                          <Input
                            id="flightsPerYear"
                            type="number"
                            value={userData.flightsPerYear}
                            onChange={handleChange}
                          />
                        </FormGroup>
                      </Col>
                    </Row>
                  </Collapse>

                  {/* Additional sections omitted for brevity */}

                  <Button color="primary" type="submit">
                    Submit
                  </Button>
                </Form>
              </CardBody>
            </Card>
          </Col>
        </Row>
      </Container>
    </>
  );
};

export default CarbonFootprintInput;
